module TopModule (
    input clk,
    input reset,
    output shift_ena
);

reg [3:0] sr;

assign shift_ena = sr[0];

always @(posedge clk) begin
    if (reset) begin
        sr <= 4'b1111;
    end else begin
        sr <= {1'b0, sr[3:1]};
    end
end

endmodule

